func TestScratchEvictionOrderCapacity1(t *testing.T) {
	c := NewLRUCache(1)
	c.Put(1, 10)
	c.Put(2, 20)
	if _, ok := c.Get(1); ok {
		t.Fatal("key 1 should be evicted at capacity 1")
	}
	if v, ok := c.Get(2); !ok || v != 20 {
		t.Fatalf("Get(2) = (%d, %v), want (20, true)", v, ok)
	}
}

func TestScratchGetThenEvictUsesMostRecent(t *testing.T) {
	c := NewLRUCache(3)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(3, 3)
	c.Get(1) // 1 most recent; 2 now LRU
	c.Get(2) // 2 most recent; 3 now LRU
	c.Put(4, 4) // evicts 3
	if _, ok := c.Get(3); ok {
		t.Fatal("key 3 should be evicted (least recently used)")
	}
	if v, ok := c.Get(1); !ok || v != 1 {
		t.Fatalf("Get(1) = (%d, %v), want (1, true)", v, ok)
	}
	if v, ok := c.Get(2); !ok || v != 2 {
		t.Fatalf("Get(2) = (%d, %v), want (2, true)", v, ok)
	}
}

