package lru

import "testing"

// Scratch verification test (deleted before completion). Encodes the required
// LRU semantics: Get and Put both count as uses; eviction removes the least
// recently used key.

func TestScratchGetMarksAsUsed(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 10)
	c.Put(2, 20)
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Fatalf("Get(1) = (%d, %v), want (10, true)", v, ok)
	}
	// Reading 1 makes 2 the least recently used key.
	c.Put(3, 30)
	if _, ok := c.Get(2); ok {
		t.Fatal("key 2 evicted, want key 2 to survive (1 was just read)")
	}
	if v, ok := c.Get(1); !ok || v != 10 {
		t.Fatalf("Get(1) = (%d, %v), want (10, true)", v, ok)
	}
	if v, ok := c.Get(3); !ok || v != 30 {
		t.Fatalf("Get(3) = (%d, %v), want (30, true)", v, ok)
	}
}

func TestScratchPutExistingMarksAsUsed(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 10)
	c.Put(2, 20)
	c.Put(1, 11) // update counts as a use
	c.Put(3, 30)
	if v, ok := c.Get(1); !ok || v != 11 {
		t.Fatalf("Get(1) = (%d, %v), want (11, true)", v, ok)
	}
	if _, ok := c.Get(2); ok {
		t.Fatal("key 2 evicted, want key 2 to survive (1 was just put)")
	}
}

func TestScratchGetMissDoesNotDisturbOrder(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 10)
	c.Put(2, 20)
	if v, ok := c.Get(99); ok || v != 0 {
		t.Fatalf("Get(99) = (%d, %v), want (0, false)", v, ok)
	}
	c.Put(3, 30)
	if _, ok := c.Get(1); ok {
		t.Fatal("key 1 evicted, want key 1 to be evicted only if LRU: miss must not touch order")
	}
}

func TestScratchEvictionOrderCapacity1(t *testing.T) {
	c := NewLRUCache(1)
	c.Put(1, 10)
	c.Put(2, 20)
	if _, ok := c.Get(1); ok {
		t.Fatal("key 1 should be evicted at capacity 1")
	}
	if v, ok := c.Get(2); !ok || v != 20 {
		t.Fatalf("Get(2) = (%d, %v), want (20, true)", v, ok)
	}
}

func TestScratchGetThenEvictUsesMostRecent(t *testing.T) {
	c := NewLRUCache(3)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(3, 3)
	c.Get(1) // 1 most recent; 2 now LRU
	c.Get(2) // 2 most recent; 3 now LRU
	c.Put(4, 4) // evicts 3
	if _, ok := c.Get(3); ok {
		t.Fatal("key 3 should be evicted (least recently used)")
	}
	if v, ok := c.Get(1); !ok || v != 1 {
		t.Fatalf("Get(1) = (%d, %v), want (1, true)", v, ok)
	}
	if v, ok := c.Get(2); !ok || v != 2 {
		t.Fatalf("Get(2) = (%d, %v), want (2, true)", v, ok)
	}
}

